public function DBInsertNoReload()
{
      $iNextId = ItopCounter::IncClass(get_class($this));
      $sRef = $this->MakeIssueReference($iNextId);
      $this->SetIfNull('reference', $sRef);
      $iKey = parent::DBInsertNoReload();
      return $iKey;
}

	public function DoCheckToWrite()
	{
        parent::DoCheckToWrite();

        // Can't have itself as parent
        if (!$this->IsNew() && ($this->Get('parent_issue_id') == $this->GetKey()))
        {
          $this->m_aCheckIssues[] = Dict::Format('Class:AHWSIssue/Error:CannotAssignParentIssueIdToSelf');
        }	
	}

	public function PrefillTransitionForm(&$value)
	{
        if ($value['stimulus'] == 'ev_resolve') {
        			$oDateFormat = AttributeDateTime::GetFormat();
			        $oDateTime = new DateTime('now');
              $this->Set('resolution_date', $oDateTime->format($oDateFormat));
        }
	    return true;
	}

    public function GetInitialStateAttributeFlags($sAttCode, &$aReasons = array())	{
		if ($sAttCode == 'update_date' || $sAttCode == 'creation_date' || $sAttCode == 'resolution_date' || $sAttCode == 'resolution_code')
		{
		    return OPT_ATT_HIDDEN;
		}

		return parent::GetInitialStateAttributeFlags($sAttCode, $aReasons);
	}
